CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY AUTOINCREMENT,guest_name TEXT NOT NULL,phone TEXT NOT NULL,stay_type TEXT NOT NULL,plan TEXT NOT NULL,check_in TEXT NOT NULL,check_out TEXT NOT NULL,adults INTEGER NOT NULL DEFAULT 1,children INTEGER NOT NULL DEFAULT 0,notes TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','rejected')),total_amount INTEGER,paid_amount INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT(datetime('now'))); CREATE INDEX IF NOT EXISTS bookings_created_at_idx ON bookings(created_at);